import json, sys, os, glob, datetime
D="/root/.claude/projects/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/subagents/workflows/wf_603242ca-111"
labels={}
for m in glob.glob(D+"/agent-*.meta.json"):
    labels[os.path.basename(m)[6:-10]]=json.load(open(m))['description']
def ts(s): return datetime.datetime.fromisoformat(s.replace('Z','+00:00')).timestamp()
out=open(sys.argv[1],'w')
summary=[]
for f in sorted(glob.glob(D+"/agent-*.jsonl")):
    aid=os.path.basename(f)[6:-6]; lab=labels.get(aid,aid)
    lines=[json.loads(l) for l in open(f)]
    seen=set(); calls={}; order=[]
    msgtok={}  # msg id -> tokens (write)
    cur_msg=None
    tot=0; first=None; last=None
    # assistant message order and per-message tokens
    for d in lines:
        t=d.get('timestamp')
        if t:
            first=first or t; last=t
        if d.get('type')=='assistant':
            m=d['message']; mid=m.get('id'); u=m.get('usage') or {}
            if mid not in seen:
                seen.add(mid)
                w=(u.get('cache_creation_input_tokens') or 0)+(u.get('input_tokens') or 0)
                msgtok[mid]=w; tot+=w
            for c in m.get('content',[]):
                if c.get('type')=='tool_use':
                    calls[c['id']]={'mid':mid,'t0':ts(t),'name':c['name'],'inp':c['input']}
                    order.append(c['id'])
        elif d.get('type')=='user':
            m=d.get('message',{}); cs=m.get('content')
            if isinstance(cs,list):
                for c in cs:
                    if c.get('type')=='tool_result' and c.get('tool_use_id') in calls:
                        r=c.get('content'); 
                        txt=r if isinstance(r,str) else ' '.join(x.get('text','') for x in r if isinstance(x,dict))
                        calls[c['tool_use_id']]['t1']=ts(t); calls[c['tool_use_id']]['rlen']=len(txt); calls[c['tool_use_id']]['res']=txt
    # message sequence to find next message after each call
    mids=[]; 
    for d in lines:
        if d.get('type')=='assistant':
            mid=d['message'].get('id')
            if not mids or mids[-1]!=mid: mids.append(mid)
    pos={m:i for i,m in enumerate(mids)}
    summary.append((lab,aid,tot,first,last,len(order)))
    for i,cid in enumerate(order):
        c=calls[cid]; inp=c['inp']
        if c['name']=='Bash': cmd=inp.get('command','')
        elif c['name'] in ('Read',): cmd='READ '+inp.get('file_path','')+' off=%s lim=%s'%(inp.get('offset'),inp.get('limit'))
        elif c['name'] in ('Grep','Glob'): cmd=c['name'].upper()+' '+json.dumps(inp)[:300]
        else: cmd=c['name']+' '+json.dumps(inp)[:200]
        p=pos.get(c['mid'],0); nxt=mids[p+1] if p+1<len(mids) else None
        tok_issue=msgtok.get(c['mid'],0); tok_next=msgtok.get(nxt,0) if nxt else 0
        dt=(c.get('t1',c['t0'])-c['t0'])
        res=c.get('res','').replace('\n','\\n')
        out.write('\t'.join([lab, str(i), datetime.datetime.utcfromtimestamp(c['t0']).strftime('%H:%M:%S'), '%.0f'%dt, str(c.get('rlen',0)), str(tok_issue), str(tok_next), c['mid'] or '', cmd.replace('\n','\\n').replace('\t',' ')[:1500], res[:600]])+'\n')
for s in summary: print('\t'.join(map(str,s)))
EOF
